package com.wissenup.domain.fee.entity; import jakarta.persistence.*;import lombok.*;import java.time.*;import java.math.*;
@Entity @Table(name="student_fees") @Getter@Setter@Builder@NoArgsConstructor@AllArgsConstructor public class StudentFee{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="student_fee_id")private Long studentFeeId;@Column(name="organization_id")private Long organizationId;@Column(name="student_id")private Long studentId;@Column(name="academic_year_id")private Long academicYearId;@Column(name="class_id")private Long classId;@Column(name="fee_structure_id")private Long feeStructureId;@Column(name="fee_type_id")private Long feeTypeId;@Column(name="fee_category")private String feeCategory;@Column(name="total_amount")private BigDecimal totalAmount;@Column(name="discount_amount")private BigDecimal discountAmount;@Column(name="discount_reason")private String discountReason;@Column(name="paid_amount")private BigDecimal paidAmount;@Column(name="balance_amount")private BigDecimal balanceAmount;@Column(name="due_date")private LocalDate dueDate;@Column(name="payment_status")private String paymentStatus;private String status;@Column(name="created_at")private LocalDateTime createdAt;@Column(name="created_by")private Long createdBy;@Column(name="updated_at")private LocalDateTime updatedAt;@Column(name="updated_by")private Long updatedBy;@Version private Long version;@PrePersist void c(){if(discountAmount==null)discountAmount=BigDecimal.ZERO;if(paidAmount==null)paidAmount=BigDecimal.ZERO;if(status==null)status="ACTIVE";if(paymentStatus==null)paymentStatus="PENDING";if(createdAt==null)createdAt=LocalDateTime.now();}@PreUpdate void u(){updatedAt=LocalDateTime.now();}}
